public class SnappyCompressor implements ICompressor {
    @Getter
    private static final SnappyCompressor instance = new SnappyCompressor();

    @Override
    public byte[] compress(byte[] data) { return Snappy.compress(data); }

    @Override
    public byte[] decompress(byte[] data) { return Snappy.uncompress(data); }
}

private String hashKey(String employeeNumber) {
    return String.valueOf(Math.abs(employeeNumber.hashCode() % hashSize()));
}
private int hashSize() { return 256; }

public void set(List<EmployeeErpVO> allEmployee) {
    Map<String, List<EmployeeErpVO>> kvs = groupByHash(allEmployee);
    fillLackedKeyForAllEmployee(kvs);   // 缺失桶位填充空列表，保证 256 桶完整
    set(kvs);
}

private void fillLackedKeyForAllEmployee(Map<String, List<EmployeeErpVO>> groupByHashKey) {
    Sets.SetView<String> lackHashKeys = Sets.difference(new HashSet<>(allHashKey()), groupByHashKey.keySet());
    if (!lackHashKeys.isEmpty()) {
        lackHashKeys.forEach(k -> groupByHashKey.put(k, Collections.emptyList()));
    }
}

protected EmployeeErpVO loadFromDb(String key) {
    try {
        return unifiedEmployeeUtil.getEmployeeErpInfo(key);      // 正常回源 OA/Chidori
    } catch (Exception e) {
        // 查询失败尝试从全量缓存中获取（降级）
        EmployeeErpVO employeeErpVO = allEmployeeCache.getOneOrNull(key);
        if (employeeErpVO != null) {
            log.warn("employee cache load error, key:{}, downgrade to load from allEmployeeCache", key, e);
        } else {
            log.error("employee cache load error, key:{}", key, e);   // 降级也没有 → error + null
        }
        return employeeErpVO;
    }
}
